/**
 * Talaria Flow — browser Supabase client and session helpers.
 *
 * The browser only ever holds the anon key (public/assets/js/env.js, generated by scripts/build.mjs).
 * Login / signup / reset go through /api/auth/* (rate limit + Turnstile + zod) and the resulting
 * session is handed to supabase-js with setSession(). Every time supabase-js signs in or rotates the
 * token, the access token is mirrored into an HttpOnly cookie via POST /api/auth/session so that
 * middleware.ts can guard /account and /admin on the server.
 */
(function () {
  window.TF = window.TF || {};

  function getEnv() {
    var env = window.__ENV || {};
    return {
      url: String(env.SUPABASE_URL || '').trim(),
      anonKey: String(env.SUPABASE_ANON_KEY || '').trim(),
      turnstileSiteKey: String(env.TURNSTILE_SITE_KEY || '').trim(),
    };
  }

  var env = getEnv();
  var client = null;
  var VENDOR_SRC = '/assets/js/vendor/supabase.js';
  var AUTH_PAGE = /\/(account|admin|login|signup)(\/|$)/.test(location.pathname);

  function createClient() {
    if (!window.supabase || !env.url || !env.anonKey) return null;
    try {
      return window.supabase.createClient(env.url, env.anonKey, {
        auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true, flowType: 'pkce' },
      });
    } catch (e) {
      return null;
    }
  }

  /** supabase-js persists the session under sb-<ref>-auth-token; its presence means "probably signed in". */
  function hasStoredSession() {
    try {
      for (var i = 0; i < localStorage.length; i++) {
        if (/^sb-.*-auth-token$/.test(localStorage.key(i) || '')) return true;
      }
    } catch (e) {}
    return false;
  }

  var vendorLoading = null;
  function loadVendor() {
    if (window.supabase) return Promise.resolve();
    if (vendorLoading) return vendorLoading;
    vendorLoading = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = VENDOR_SRC;
      s.async = true;
      s.onload = function () { resolve(); };
      s.onerror = function () { vendorLoading = null; reject(new Error('supabase-js load failed')); };
      document.head.appendChild(s);
    });
    return vendorLoading;
  }

  window.TF.getEnv = getEnv;
  window.TF.client = null;
  window.TF.getClient = function () { return window.TF.client; };

  // ---- small helpers -------------------------------------------------------
  window.TF.escapeHtml = function (value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  };

  async function accessToken(forceRefresh) {
    if (!client) return null;
    try {
      if (forceRefresh) await client.auth.refreshSession();
      var res = await client.auth.getSession();
      return res && res.data && res.data.session ? res.data.session.access_token : null;
    } catch (e) { return null; }
  }

  /** fetch() to /api/* with JSON body and the member's bearer token. Resolves {ok, status, body}. */
  window.TF.api = async function (path, opts) {
    opts = opts || {};
    var headers = Object.assign({ accept: 'application/json' }, opts.headers || {});
    var body = opts.body;
    if (body !== undefined && typeof body !== 'string') {
      headers['content-type'] = 'application/json';
      body = JSON.stringify(body);
    }
    async function send(token) {
      var h = Object.assign({}, headers);
      if (token) h.authorization = 'Bearer ' + token;
      return fetch(path, { method: opts.method || (body !== undefined ? 'POST' : 'GET'), headers: h, body: body, credentials: 'same-origin' });
    }
    var token = opts.auth === false ? null : await accessToken();
    var res = await send(token);
    if (res.status === 401 && opts.auth !== false) {
      var next = await accessToken(true);
      if (next && next !== token) res = await send(next);
    }
    var out = null;
    try { out = await res.json(); } catch (e) { out = null; }
    return { ok: res.ok, status: res.status, body: out || {} };
  };

  // ---- Cloudflare Turnstile (invisible) -----------------------------------
  var turnstileLoading = null;
  function loadTurnstile() {
    if (window.turnstile) return Promise.resolve(window.turnstile);
    if (turnstileLoading) return turnstileLoading;
    turnstileLoading = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
      s.async = true;
      s.onload = function () { resolve(window.turnstile); };
      s.onerror = function () { turnstileLoading = null; reject(new Error('turnstile load failed')); };
      document.head.appendChild(s);
    });
    return turnstileLoading;
  }
  /** Resolve a Turnstile token for `action`, or '' when no site key is configured. */
  window.TF.turnstile = async function (action) {
    if (!env.turnstileSiteKey) return '';
    var ts = await loadTurnstile();
    return new Promise(function (resolve) {
      var host = document.createElement('div');
      host.style.cssText = 'position:fixed;left:-9999px;top:0;width:0;height:0;overflow:hidden';
      document.body.appendChild(host);
      var done = false;
      function finish(token) {
        if (done) return;
        done = true;
        try { if (id) ts.remove(id); } catch (e) {}
        host.remove();
        resolve(token || '');
      }
      var id = ts.render(host, {
        sitekey: env.turnstileSiteKey,
        action: action,
        size: 'invisible',
        execution: 'execute',
        callback: finish,
        'error-callback': function () { finish(''); },
        'expired-callback': function () { finish(''); },
      });
      ts.execute(id);
      setTimeout(function () { finish(''); }, 15000);
    });
  };

  // ---- session cookie sync (server-side guard) ----------------------------
  var lastCookieToken = null;
  async function syncSessionCookie(session) {
    var token = session && session.access_token;
    if (!token) {
      if (lastCookieToken !== '') {
        lastCookieToken = '';
        try { await drain(fetch('/api/auth/session', { method: 'DELETE', credentials: 'same-origin' })); } catch (e) {}
      }
      return;
    }
    if (token === lastCookieToken) return;
    lastCookieToken = token;
    try {
      await drain(fetch('/api/auth/session', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ access_token: token, expires_at: session.expires_at }),
      }));
    } catch (e) {}
  }
  // An unread fetch body keeps the request "in flight" in Chromium (network never goes idle).
  function drain(p) { return p.then(function (r) { return r.text(); }); }
  window.TF.syncSessionCookie = syncSessionCookie;

  // ---- session state --------------------------------------------------------
  function isAdminProfile(profile) {
    return Boolean(profile && (profile.is_admin === true || profile.role === 'admin'));
  }

  var sessionListeners = [];
  var sessionState = { user: null, profile: null, isAdmin: false };
  function publishSession(state) {
    sessionState = state || { user: null, profile: null, isAdmin: false };
    sessionListeners.slice().forEach(function (fn) {
      try { fn(sessionState); } catch (err) {}
    });
  }

  window.TF.getCurrentUser = async function () {
    if (!client) return { user: null, profile: null, isAdmin: false };
    var sessRes = await client.auth.getSession();
    var session = sessRes && sessRes.data && sessRes.data.session;
    if (!session || !session.user) return { user: null, profile: null, isAdmin: false };
    var user = session.user;
    var profileRes = await client.from('profiles')
      .select('id, email, is_admin, role, name, first_name, last_name, country, lang, notify, created_at, resubmit_note, blocked')
      .eq('id', user.id).maybeSingle();
    if (profileRes.error && /blocked/i.test(profileRes.error.message || '')) {
      profileRes = await client.from('profiles')
        .select('id, email, is_admin, role, name, first_name, last_name, country, lang, notify, created_at, resubmit_note')
        .eq('id', user.id).maybeSingle();
    }
    if (profileRes.error && /resubmit_note/i.test(profileRes.error.message || '')) {
      profileRes = await client.from('profiles')
        .select('id, email, is_admin, role, name, first_name, last_name, country, lang, notify, created_at')
        .eq('id', user.id).maybeSingle();
    }
    var profile = profileRes.data || { id: user.id, email: user.email };
    return { user: user, profile: profile, isAdmin: isAdminProfile(profile) };
  };

  window.TF.useSession = function (fn) {
    if (typeof fn !== 'function') return function () {};
    sessionListeners.push(fn);
    try { fn(sessionState); } catch (err) {}
    return function () { sessionListeners = sessionListeners.filter(function (x) { return x !== fn; }); };
  };
  window.TF.refreshSession = async function () {
    var state = await window.TF.getCurrentUser();
    publishSession(state);
    return state;
  };
  window.TF.getSession = function () { return sessionState; };

  /**
   * Create the client once supabase-js is on the page. Idempotent: called here, by nav.js after a
   * soft navigation pulled in the vendor script, and by ensureClient().
   */
  function initClient() {
    if (client || !window.supabase) return client;
    client = createClient();
    window.TF.client = client;
    if (!client) {
      if (window.tfToast && AUTH_PAGE) window.tfToast('Backend is not configured (SUPABASE_URL / SUPABASE_ANON_KEY).');
      return null;
    }
    client.auth.onAuthStateChange(function (event, session) {
      // INITIAL_SESSION fires with null on every page load before localStorage is read.
      // Clearing the HttpOnly cookie then logs the visitor out immediately after /api/auth/login.
      if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'USER_UPDATED') syncSessionCookie(session);
      if (event === 'INITIAL_SESSION' && session) syncSessionCookie(session);
      if (event === 'SIGNED_OUT') syncSessionCookie(null);
      window.TF.refreshSession();
    });
    window.TF.refreshSession();
    return client;
  }
  window.TF.initClient = initClient;

  /** Resolve the client, downloading supabase-js on demand (public pages ship without it). */
  window.TF.ensureClient = async function () {
    if (client) return client;
    if (!env.url || !env.anonKey) return null;
    try { await loadVendor(); } catch (e) { return null; }
    return initClient();
  };

  /** Sign in with the session returned by /api/auth/login or /api/auth/signup. */
  window.TF.adoptSession = async function (session) {
    if (!session) return null;
    await window.TF.ensureClient();
    if (!client) return null;
    var res = await client.auth.setSession({ access_token: session.access_token, refresh_token: session.refresh_token });
    await syncSessionCookie(res && res.data && res.data.session);
    return window.TF.refreshSession();
  };

  window.TF.signOut = async function () {
    try { if (client) await client.auth.signOut(); } catch (e) {}
    await syncSessionCookie(null);
    publishSession(null);
  };

  window.TF.requireAuth = async function () {
    try {
      var state = await window.TF.getCurrentUser();
      if (!state.user) {
        window.location.href = '/login/?redirect=' + encodeURIComponent(window.location.pathname || '/account/');
        return null;
      }
      return {
        user: state.user,
        profile: state.profile,
        isAdmin: state.isAdmin,
        isEmailVerified: Boolean(state.user.email_confirmed_at || state.user.confirmed_at),
      };
    } catch (err) {
      window.location.href = '/login/';
      return null;
    }
  };

  window.TF.requireAdmin = async function () {
    try {
      var state = await window.TF.getCurrentUser();
      if (!state.user || !state.isAdmin) {
        // The server already answers 404 here; mirror it if the page was served from cache.
        window.location.replace('/404');
        return null;
      }
      return state;
    } catch (err) {
      window.location.replace('/404');
      return null;
    }
  };

  // Auth/account/admin pages include supabase-js in their markup. Public pages only fetch it when a
  // stored session suggests the visitor is signed in, so anonymous visitors never download it.
  if (window.supabase) initClient();
  else if (AUTH_PAGE || hasStoredSession()) window.TF.ensureClient();
  else publishSession(null);
})();
